/*
 * ONE LOAD PER COURSE, SHARED BY EVERY CALLER.
 *
 * OBSERVED in the running app's network log: `personalFinance.bundle` was fetched TWENTY times,
 * 664.7 KB each — about 13MB of the same module. Four screens call this on mount with no cache
 * and no dedupe between them: home.tsx, learn.tsx, lesson.tsx and start.tsx. Opening
 * Learn, backing out and opening it again pays again.
 *
 * THE PROMISE IS CACHED, NOT THE RESULT, which is what makes this a dedupe as well as a cache:
 * two screens mounting in the same tick share one in-flight load instead of racing two.
 *
 * A REJECTION IS EVICTED. Caching a failed promise forever would turn one dropped chunk into a
 * course that can never load again for the life of the process — and learn.tsx has a retry button
 * whose whole purpose is to recover from exactly that. The `attempt` counter it bumps would have
 * become useless.
 *
 * Honest scope: in production `import()` already caches the MODULE, so this mainly saves the
 * repeated promise setup and the duplicate in-flight loads. In development, where Metro re-serves
 * the lazy bundle, it saves the 664KB refetch outright.
 *
 * IT LIVES HERE, NOT IN courseIndex.ts, AND THAT IS THE WHOLE POINT. courseIndex.ts is OWNED by
 * ./scripts/sync-curriculum.sh, which deletes and rewrites it on every run. This cache was
 * hand-written into that generated file and a routine sync destroyed it silently — the sync
 * reported success, tsc passed, `npm run check` passed, and the only symptom would have been the
 * 13MB of refetching quietly coming back. index.ts and availability.ts are the files in this folder
 * the sync leaves alone (they are not in its "Files this script OWNS" list or its `rm -f` line), so
 * anything native-only belongs here, wrapping the generated export rather than editing it.
 */
const lessonCache = new Map<string, Promise<PathwayLesson[]>>();

/*
 * QUESTIONS AND ANSWER OPTIONS, SHORTENED FOR A PHONE.
 *
 * Measured over the 1,307 choice steps: prompts run to a median of 165 characters with a longest of
 * 467, and 76% are over 120. Options are worse in the tail, median 52 but a longest of 1,030, with
 * 45% over 60. On a 393pt screen a long prompt pushes the options below the fold, which is the same
 * failure that made the explanation page necessary.
 *
 * Applied to the AUTHORED step, before normalizeStep shuffles anything. Only the strings change and
 * nothing is reordered, so `correct` still points at the same answer and the shuffle downstream
 * still pairs each option with its own authored feedback.
 *
 * `shortenOptions` is all or nothing per question and refuses any set where two options would
 * collapse together or where the correct one would be left conspicuously the longest. See
 * question.ts for why that matters more than the length does.
 *
 * Exported only so scripts/lazy-deck-pin.mjs can rebuild the eager result and prove the lazy
 * getter below returns byte-identical steps. UI code has no reason to call it.
 */
export function withShorterQuestions(step: LessonStep): LessonStep {
  const s = step as Record<string, any>;

  /*
   * THE HOOK OPENER is the first screen of all 300 lessons and was the longest thing left in the
   * corpus: `fact` at a median of 338 characters and a longest of 894, with `outcome` adding
   * another 241 underneath it, on a screen that also carries a title, a chart and a button.
   *
   * `fact` uses shortenHookFact, not shortenField: a fact is a setup and a payoff, and shortenField
   * kept only the setup, so investing-fundamentals L1's opener said "$100 in a drawer in 1995 is
   * still $100 today" with the two-thirds-lost payoff cut off (question.ts has the measurement).
   */
  if (s.type === 'hookOpener') {
    return {
      ...s,
      fact: shortenHookFact(s.fact, STEP_TEXT_BUDGET.fact),
      outcome: shortenField(s.outcome, STEP_TEXT_BUDGET.outcome),
    } as LessonStep;
  }

  /*
   * STAKES DETAIL only renders when neither panel has an authored visual, but when it does it is
   * two paragraphs of about 305 characters inside panels that already have to share one screen.
   */
  if (s.type === 'stakesCard') {
    return {
      ...s,
      without: s.without ? { ...s.without, detail: shortenField(s.without.detail, STEP_TEXT_BUDGET.stakesDetail) } : s.without,
      with: s.with ? { ...s.with, detail: shortenField(s.with.detail, STEP_TEXT_BUDGET.stakesDetail) } : s.with,
    } as LessonStep;
  }

  /*
   * VOCABULARY definitions are shown one per beat, so the median of 154 is survivable and this cap
   * is for the tail, which reaches 288. The term, the example and the sentence are left alone: they
   * are already short, and the example is the thing that makes an abstract definition concrete.
   */
  if (s.type === 'keyTermsCards') {
    return {
      ...s,
      terms: (s.terms ?? []).map((t: Record<string, any>) => ({
        ...t,
        definition: shortenField(t.definition, STEP_TEXT_BUDGET.definition),
      })),
    } as LessonStep;
  }

  if (s.type === 'quiz' || s.type === 'microCheck' || s.type === 'visualInteractive') {
    return { ...s, question: shortenPrompt(s.question), options: shortenOptions(s.options ?? [], s.correct ?? 0) } as LessonStep;
  }
  if (s.type === 'fillBlank') {
    /*
     * The sentence is NOT shortened. It carries the `___` slot the renderer splits on, and trimming
     * it can remove the blank or the words either side of it that make the sentence gradeable.
     * Its options still get the same treatment as any other set.
     */
    return { ...s, options: shortenOptions(s.options ?? [], s.correct ?? 0) } as LessonStep;
  }
  if (s.type === 'scenario') {
    const choices = (s.choices ?? []) as { label: string; correct: boolean }[];
    const correct = Math.max(0, choices.findIndex((c) => c.correct));
    const labels = shortenOptions(choices.map((c) => c.label), correct);
    return {
      ...s,
      situation: shortenPrompt(s.situation),
      choices: choices.map((c, i) => ({ ...c, label: labels[i] })),
    } as LessonStep;
  }
  return step;
}

/*
 * DECKS ARE DERIVED PER LESSON, ON FIRST READ OF `steps`, not for the whole course at load.
 *
 * This used to map all 25 lessons through deriveDeck the first time anything loaded a course. Home
 * and Learn call loadCourseLessons only for num, title and xp, so a cold Home paid for every deck
 * in the course (721 corpus-wide) to show one lesson title. Measured in node, interpreter only
 * (--no-opt --no-sparkplug --no-maglev, standing in for Hermes): Home's course load took about 65ms
 * for investing-fundamentals and personal-finance.
 *
 * `steps` is an enumerable, configurable getter. The first read runs this lesson's steps through
 * withShorterQuestions and deriveDeck, then redefines `steps` as a plain writable data property
 * holding the result, so later reads, spreads and JSON.stringify see an ordinary array. The output
 * is byte-identical to the old eager pass; scripts/lazy-deck-pin.mjs checks that across all 300
 * lessons, and that metadata reads derive nothing.
 */
let deckDerivations = 0;

/** How many decks this process has derived. Read-only; exists for scripts/lazy-deck-pin.mjs. */
export function deckDerivationCount(): number {
  return deckDerivations;
}

function mobileSteps(authored: LessonStep[], courseId: string, lessonNum: number): LessonStep[] {
  // Every step goes through here: a lesson with no heavy step still has questions to shorten.
  return authored.map((step, index) => {
    if (!isHeavyStep(step)) return withShorterQuestions(step);
    deckDerivations += 1;
    const id = stepId(courseId, lessonNum, index, step);
    const deck = deriveDeck(step, id);
    // A null deck cannot happen for a heavy step, and mobile-deck-audit.mjs fails the build if
    // one ever does. Keeping the authored step is the safe fallback: long, but never blank.
    if (!deck) return step;
    /*
     * Hand-placed parts (dial, lever, scene) go in HERE, after derivation, and are handed the RAW
     * authored steps. Measured during the lever review: fed the already-wrapped steps (mobileDeck
     * objects with no sliders or insights), buildLever returned null and the guess card silently
     * stayed. `authored` is also the array `index` counts in, so the placement key and stepId agree.
     * No placement for this position returns the same deck object, so every other deck is untouched
     * (scripts/deck-derive-polish-pin.mjs checks that identity over all 721).
     */
    return applyPlacement(deck, id, authored) as unknown as LessonStep;
  });
}

/*
 * THE MOBILE LESSON LAYER, applied here and only here.
 *
 * On iOS every `teachingSlide` and every `interactiveGraph` is replaced by a deck of three or four
 * cards derived from it. That is 721 of the 4,050 steps in the corpus and, measured, essentially
 * all of the prose: the median graph step runs 2,557 characters and the median teaching slide
 * 1,636, against a phone viewport that holds about 1,000. The web app keeps showing the authored
 * step exactly as written. This is the point where the two products diverge.
 *
 * ONE STEP IN, ONE STEP OUT. A deck replaces its source step 1:1, so `lesson.steps.length` is
 * unchanged and the progress bar, the step counter and every saved position keep meaning what they
 * meant. The cards are paged INSIDE the deck. Expanding one step into four here would have moved
 * every learner's saved position the moment this shipped.
 *
 * IT IS APPLIED AT THE CHOKE POINT for the same reason the retired-step filter and the reading
 * level are (see courseIndex.ts): every screen, the dev preview and saved progress then agree on
 * how long a lesson is. Doing it in the renderer instead would let those three disagree.
 *
 * SCRIPTS THAT CHECK PARITY AGAINST WEB MUST IMPORT `./courseIndex` DIRECTLY, not this module, or
 * they will compare native decks against web steps and fail for the wrong reason.
 */
/*
 * PRACTICE IS CAPPED AT FIVE SCREENS ON THE PHONE (owner, 2026-10-01: "the quizzing is a bit
 * excessive"; chose "cap at 5, keep the variety"). Measured before: 261 of 300 lessons ran more
 * than five practice screens after the vocab part, median eight, and quantitative-analysis:1 ran
 * nine (fill-in, quiz, tap reveal, drag sort, scenario, slider, true or false, match, quiz).
 *
 * VARIETY FIRST. One screen of each KIND is kept before any kind gets a second, taken in the
 * priority below (the kinds where the learner does something with the idea lead, the reveal and
 * fill-in kinds trail), then any room left fills in authored order. Kept steps stay in authored
 * order. Budget is in SCREENS, so a progressiveCalc that expands to four screens costs four.
 *
 * ONLY QUESTIONS ARE CUT. A step whose kind is not in PRACTICE_PRIORITY (a teaching deck, a
 * concept, an explorable that happens to sit after the vocab part) is always kept and costs
 * nothing: the cap is on quizzing, never on teaching.
 *
 * Applied here, after the decks, so the web corpus (courseIndex.ts) and every parity check against
 * it are untouched: this is a phone-only cut, like the decks themselves. Every placement key and
 * stepId sits in the learn part, before practice, so none of them move.
 */
export const PRACTICE_SCREEN_CAP = 5;
const PRACTICE_PRIORITY = [
  'scenario', 'slider', 'dragSort', 'match', 'quiz', 'trueFalse', 'buildIt', 'decisionTree',
  'calculator', 'matchingPairs', 'sorting', 'budgetBuilder', 'scenarioSim', 'visualInteractive',
  'microCheck', 'fillBlank', 'tapReveal', 'progressiveCalc',
];

export function withCappedPractice(steps: LessonStep[]): LessonStep[] {
  const types = steps.map((s) => (s as { type?: string }).type ?? '');
  const practice = segmentsOf(types, false).find((seg) => seg.kind === 'practice');
  if (!practice) return steps;
  const start = practice.first - 1;
  const all = steps.slice(start).map((step, i) => ({ step, i, type: types[start + i], screens: Math.max(1, expandSteps([step]).length) }));
  const pool = all.filter((p) => PRACTICE_PRIORITY.includes(p.type));
  if (pool.reduce((n, p) => n + p.screens, 0) <= PRACTICE_SCREEN_CAP) return steps;

  const rank = (t: string) => { const r = PRACTICE_PRIORITY.indexOf(t); return r < 0 ? PRACTICE_PRIORITY.length : r; };
  const firstOfKind: typeof pool = [];
  for (const p of pool) if (!firstOfKind.some((q) => q.type === p.type)) firstOfKind.push(p);
  firstOfKind.sort((a, b) => rank(a.type) - rank(b.type) || a.i - b.i);

  const keep = new Set<number>();
  let used = 0;
  const take = (p: (typeof pool)[number]) => {
    if (keep.has(p.i) || used + p.screens > PRACTICE_SCREEN_CAP) return;
    keep.add(p.i);
    used += p.screens;
  };
  firstOfKind.forEach(take);
  pool.forEach(take);
  // Never an empty practice part: a step bigger than the whole budget is still better than none.
  if (keep.size === 0 && pool[0]) keep.add(pool[0].i);
  return [...steps.slice(0, start), ...all.filter((p) => keep.has(p.i) || !PRACTICE_PRIORITY.includes(p.type)).map((p) => p.step)];
}

function withMobileDecks(lessons: PathwayLesson[], courseId: string): PathwayLesson[] {
  return lessons.map((lesson) => {
    const authored = lesson.steps;
    const out = { ...lesson };
    Object.defineProperty(out, 'steps', {
      enumerable: true,
      configurable: true,
      get() {
        const steps = withCappedPractice(mobileSteps(authored, courseId, lesson.num));
        // Redefined on `out`, not `this`, so a read through a prototype or proxy still memoizes
        // on the lesson itself instead of deriving again on every read.
        Object.defineProperty(out, 'steps', { value: steps, enumerable: true, configurable: true, writable: true });
        return steps;
      },
    });
    return out;
  });
}

/** Lazily load the 25 lessons for a course. Resolves to [] for an unknown id. */
export function loadCourseLessons(courseId: string): Promise<PathwayLesson[]> {
  const hit = lessonCache.get(courseId);
  if (hit) return hit;
  const p = loadCourseLessonsUncached(courseId).then((lessons) => withMobileDecks(lessons, courseId));
  lessonCache.set(courseId, p);
  // Evict on failure so a retry can genuinely retry.
  void p.catch(() => lessonCache.delete(courseId));
  return p;
}

/**
 * One lesson with its mobile decks derived, or null when the course has no such lesson. The same
 * object loadCourseLessons holds, so a screen that already has the list sees the same steps.
 */
export async function getMobileLesson(courseId: string, num: number): Promise<PathwayLesson | null> {
  const lesson = (await loadCourseLessons(courseId)).find((l) => l.num === num) ?? null;
  if (lesson) void lesson.steps;
  return lesson;
}

